import Mathlib
import Novelty.IntegratedInformation.Core

/-!
# Advanced Integration Theory: Exclusion, Scaling, and Edge Monotonicity

Deeper theory of causal integration: scaling, edge addition, strong integration,
and the supermodularity-like inequality.
-/

noncomputable section

open Finset

namespace CausalNet

variable {n : ℕ}

/-! ## Uniform Networks -/

/-- The uniform complete network: every edge has weight `w` -/
def uniform (n : ℕ) (w : ℝ) (hw : 0 ≤ w) : CausalNet n where
  weight _ _ := w
  weight_nonneg _ _ := hw

/-
Cross-weight of the uniform network: `2 * w * |S| * |Sᶜ|`
-/
theorem uniform_crossWeight (w : ℝ) (hw : 0 ≤ w) (S : Finset (Fin n)) :
    (uniform n w hw).crossWeight S =
    2 * w * (S.card : ℝ) * ((Sᶜ).card : ℝ) := by
      unfold CausalNet.crossWeight uniform; ring;
      simpa [ Finset.card_compl ] using by ring;

/-! ## Weight Scaling -/

/-- Scale all weights by a non-negative factor -/
def scale (net : CausalNet n) (c : ℝ) (hc : 0 ≤ c) : CausalNet n where
  weight i j := c * net.weight i j
  weight_nonneg i j := mul_nonneg hc (net.weight_nonneg i j)

/-
Cross-weight scales linearly
-/
theorem crossWeight_scale (net : CausalNet n) (c : ℝ) (hc : 0 ≤ c)
    (S : Finset (Fin n)) :
    (net.scale c hc).crossWeight S = c * net.crossWeight S := by
      unfold CausalNet.crossWeight;
      simp +decide [ mul_add, Finset.mul_sum _ _ _, CausalNet.scale ]

/-
Φ scales linearly
-/
theorem phi_scale (net : CausalNet n) (hn : 2 ≤ n) (c : ℝ) (hc : 0 ≤ c) :
    (net.scale c hc).phi hn = c * net.phi hn := by
      unfold CausalNet.phi;
      simp +decide only [crossWeight_scale];
      simp +decide [ Finset.inf'_eq_csInf_image, hc ];
      rw [ ← smul_eq_mul, ← Real.sInf_smul_of_nonneg hc ];
      exact congr_arg _ ( by ext; simp +decide [ Set.mem_smul_set ] )

/-! ## Edge Addition -/

/-- Add weight `δ` to edge (i₀, j₀) -/
def addEdge (net : CausalNet n) (i₀ j₀ : Fin n) (δ : ℝ) (hδ : 0 ≤ δ) : CausalNet n where
  weight i j := if i = i₀ ∧ j = j₀ then net.weight i j + δ else net.weight i j
  weight_nonneg i j := by
    split
    · exact add_nonneg (net.weight_nonneg i j) hδ
    · exact net.weight_nonneg i j

/-
Adding a crossing edge increases cross-weight
-/
theorem crossWeight_addEdge_crossing (net : CausalNet n) (S : Finset (Fin n))
    (i₀ j₀ : Fin n) (δ : ℝ) (hδ : 0 ≤ δ)
    (hi : i₀ ∈ S) (hj : j₀ ∈ Sᶜ) :
    net.crossWeight S + δ ≤ (net.addEdge i₀ j₀ δ hδ).crossWeight S := by
      unfold CausalNet.crossWeight CausalNet.addEdge;
      simp +zetaDelta at *;
      simp +decide [ Finset.filter_eq', Finset.filter_ne', Finset.filter_and, Finset.filter_or, Finset.sum_ite, Finset.filter_inter, Finset.filter_not, Finset.card_sdiff, Finset.card_singleton, Finset.card_empty, hδ ];
      rw [ show ( ∑ x ∈ S, ∑ x_1 ∈ Sᶜ, net.weight x x_1 ) = ∑ x ∈ S, ∑ x_1 ∈ Sᶜ with x = i₀ → ¬x_1 = j₀, net.weight x x_1 + ∑ x ∈ S, ∑ x_1 ∈ ( if x = i₀ then Sᶜ else ∅ ) ∩ if j₀ ∈ S then ∅ else { j₀ }, net.weight x x_1 from ?_, show ( ∑ x ∈ Sᶜ, ∑ x_1 ∈ S, net.weight x x_1 ) = ∑ x ∈ Sᶜ, ∑ x_1 ∈ S with x = i₀ → ¬x_1 = j₀, net.weight x x_1 + ∑ x ∈ Sᶜ, ∑ x_1 ∈ ( if x = i₀ then S else ∅ ) ∩ if j₀ ∈ S then { j₀ } else ∅, net.weight x x_1 from ?_ ];
      · simp +decide [ Finset.sum_add_distrib, add_comm, add_left_comm, add_assoc, hj ];
        rw [ Finset.sum_eq_single i₀ ] <;> aesop;
      · rw [ ← Finset.sum_add_distrib ];
        refine' Finset.sum_congr rfl fun x hx => _;
        split_ifs <;> simp_all +decide [ Finset.filter_ne', Finset.filter_eq' ];
      · rw [ ← Finset.sum_add_distrib ];
        refine' Finset.sum_congr rfl fun x hx => _;
        split_ifs <;> simp_all +decide [ Finset.sum_ite, Finset.filter_ne', Finset.filter_eq' ]

/-
Adding an internal edge doesn't change cross-weight
-/
theorem crossWeight_addEdge_internal (net : CausalNet n) (S : Finset (Fin n))
    (i₀ j₀ : Fin n) (δ : ℝ) (hδ : 0 ≤ δ)
    (hi : i₀ ∈ S) (hj : j₀ ∈ S) :
    (net.addEdge i₀ j₀ δ hδ).crossWeight S = net.crossWeight S := by
      refine' congrArg₂ ( · + · ) _ _ <;> refine' Finset.sum_congr rfl fun i hi => Finset.sum_congr rfl fun j hj => _ <;> simp_all +decide [ CausalNet.addEdge ];
      · aesop;
      · grind

/-! ## Strong Integration -/

/-- A network is strongly integrated if Φ > 0 -/
def IsStronglyIntegrated (net : CausalNet n) (hn : 2 ≤ n) : Prop :=
  0 < net.phi hn

/-
A network with all positive crossing weights is strongly integrated
-/
theorem stronglyIntegrated_of_allCrossPos (net : CausalNet n) (hn : 2 ≤ n)
    (hpos : ∀ S ∈ nontrivialSubsets n, 0 < net.crossWeight S) :
    net.IsStronglyIntegrated hn := by
      obtain ⟨ S, hS ⟩ := Finset.exists_min_image ( nontrivialSubsets n ) ( fun S => net.crossWeight S ) ⟨ Finset.univ.filter ( fun x => x ≠ ⟨ 0, by linarith ⟩ ), by
        simp +decide [ nontrivialSubsets ];
        exact ⟨ ⟨ 1, by linarith ⟩, by simp +decide ⟩ ⟩
      generalize_proofs at *;
      exact lt_of_lt_of_le ( hpos S hS.1 ) ( Finset.le_inf' _ _ hS.2 )

/-
A block-diagonal network is NOT strongly integrated
-/
theorem not_stronglyIntegrated_of_blockDiag (net : CausalNet n) (hn : 2 ≤ n)
    (S : Finset (Fin n)) (hS : S.Nonempty) (hS' : S ≠ Finset.univ)
    (hbd : net.IsBlockDiag S) : ¬net.IsStronglyIntegrated hn := by
      exact fun h => h.ne' <| phi_blockDiag_zero net hn S hS hS' hbd

/-! ## The Integration Inequality -/

/-
**The Integration Inequality**: Cross-weight satisfies a supermodularity-like bound.
This connects integration theory to submodular optimization.
-/
theorem crossWeight_union_inter_bound (net : CausalNet n)
    (S T : Finset (Fin n)) :
    net.crossWeight S + net.crossWeight T ≤
    net.crossWeight (S ∪ T) + net.crossWeight (S ∩ T) +
    2 * ((∑ i ∈ S \ T, ∑ j ∈ T \ S, net.weight i j) +
         (∑ i ∈ T \ S, ∑ j ∈ S \ T, net.weight i j)) := by
           unfold CausalNet.crossWeight;
           simp +decide [ Finset.compl_eq_univ_sdiff, Finset.sum_sdiff ];
           rw [ show ( ∑ i, ∑ j ∈ S ∪ T, net.weight i j ) = ∑ i, ∑ j ∈ S, net.weight i j + ∑ i, ∑ j ∈ T, net.weight i j - ∑ i, ∑ j ∈ S ∩ T, net.weight i j from ?_, show ( ∑ i, ∑ j ∈ S ∩ T, net.weight i j ) = ∑ i, ∑ j ∈ S, net.weight i j + ∑ i, ∑ j ∈ T, net.weight i j - ∑ i, ∑ j ∈ S ∪ T, net.weight i j from ?_ ];
           · rw [ show ( ∑ i ∈ S ∪ T, ∑ j, net.weight i j ) = ∑ i ∈ S, ∑ j, net.weight i j + ∑ i ∈ T, ∑ j, net.weight i j - ∑ i ∈ S ∩ T, ∑ j, net.weight i j from ?_, show ( ∑ i ∈ S ∪ T, ∑ j ∈ S ∪ T, net.weight i j ) = ∑ i ∈ S, ∑ j ∈ S, net.weight i j + ∑ i ∈ T, ∑ j ∈ T, net.weight i j - ∑ i ∈ S ∩ T, ∑ j ∈ S ∩ T, net.weight i j + ∑ i ∈ S \ T, ∑ j ∈ T \ S, net.weight i j + ∑ i ∈ T \ S, ∑ j ∈ S \ T, net.weight i j from ?_ ];
             · linarith;
             · have h_split : ∑ i ∈ S ∪ T, ∑ j ∈ S ∪ T, net.weight i j = ∑ i ∈ S \ T, ∑ j ∈ S \ T, net.weight i j + ∑ i ∈ S \ T, ∑ j ∈ T \ S, net.weight i j + ∑ i ∈ S \ T, ∑ j ∈ S ∩ T, net.weight i j + ∑ i ∈ T \ S, ∑ j ∈ S \ T, net.weight i j + ∑ i ∈ T \ S, ∑ j ∈ T \ S, net.weight i j + ∑ i ∈ T \ S, ∑ j ∈ S ∩ T, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S \ T, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ T \ S, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S ∩ T, net.weight i j := by
                 have h_split : S ∪ T = (S \ T) ∪ (T \ S) ∪ (S ∩ T) := by
                   grind;
                 rw [ h_split, Finset.sum_union, Finset.sum_union ];
                 · repeat rw [ Finset.sum_congr rfl fun i hi => Finset.sum_union <| Finset.disjoint_right.mpr fun j hj => by aesop ] ; simp +decide [ Finset.sum_add_distrib ] ; ring;
                 · exact Finset.disjoint_left.mpr fun x hxS hxT => by aesop;
                 · exact Finset.disjoint_left.mpr ( by aesop );
               have h_split : ∑ i ∈ S, ∑ j ∈ S, net.weight i j = ∑ i ∈ S \ T, ∑ j ∈ S \ T, net.weight i j + ∑ i ∈ S \ T, ∑ j ∈ S ∩ T, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S \ T, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S ∩ T, net.weight i j := by
                 have h_split : ∑ i ∈ S, ∑ j ∈ S, net.weight i j = ∑ i ∈ S \ T, ∑ j ∈ S, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S, net.weight i j := by
                   rw [ ← Finset.sum_union ];
                   · rw [ Finset.sdiff_union_inter ];
                   · exact Finset.disjoint_left.mpr fun x hx₁ hx₂ => Finset.mem_sdiff.mp hx₁ |>.2 <| Finset.mem_inter.mp hx₂ |>.2;
                 have h_split : ∀ i ∈ S, ∑ j ∈ S, net.weight i j = ∑ j ∈ S \ T, net.weight i j + ∑ j ∈ S ∩ T, net.weight i j := by
                   intro i hi; rw [ ← Finset.sum_union ( Finset.disjoint_right.mpr fun j hj => by aesop ) ] ; congr; ext j; by_cases hj : j ∈ T <;> aesop;
                 rw [ ‹∑ i ∈ S, ∑ j ∈ S, net.weight i j = ∑ i ∈ S \ T, ∑ j ∈ S, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S, net.weight i j›, Finset.sum_congr rfl fun i hi => h_split i <| Finset.mem_sdiff.mp hi |>.1, Finset.sum_congr rfl fun i hi => h_split i <| Finset.mem_inter.mp hi |>.1 ] ; simp +decide [ Finset.sum_add_distrib ] ; ring;
               have h_split : ∑ i ∈ T, ∑ j ∈ T, net.weight i j = ∑ i ∈ T \ S, ∑ j ∈ T \ S, net.weight i j + ∑ i ∈ T \ S, ∑ j ∈ S ∩ T, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ T \ S, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ S ∩ T, net.weight i j := by
                 have h_split : ∑ i ∈ T, ∑ j ∈ T, net.weight i j = ∑ i ∈ T \ S, ∑ j ∈ T, net.weight i j + ∑ i ∈ S ∩ T, ∑ j ∈ T, net.weight i j := by
                   rw [ ← Finset.sum_union ];
                   · rw [ show T \ S ∪ S ∩ T = T by ext x; by_cases hx : x ∈ S <;> aesop ];
                   · exact Finset.disjoint_left.mpr fun x hx₁ hx₂ => Finset.mem_sdiff.mp hx₁ |>.2 <| Finset.mem_inter.mp hx₂ |>.1;
                 rw [ h_split ];
                 rw [ Finset.sum_congr rfl fun i hi => show ∑ j ∈ T, net.weight i j = ∑ j ∈ T \ S, net.weight i j + ∑ j ∈ S ∩ T, net.weight i j from ?_, Finset.sum_congr rfl fun i hi => show ∑ j ∈ T, net.weight i j = ∑ j ∈ T \ S, net.weight i j + ∑ j ∈ S ∩ T, net.weight i j from ?_ ];
                 · simp +decide only [sum_add_distrib, add_assoc];
                 · rw [ ← Finset.sum_union ];
                   · rcongr j ; by_cases hj : j ∈ S <;> aesop;
                   · exact Finset.disjoint_left.mpr fun x hx₁ hx₂ => Finset.mem_sdiff.mp hx₁ |>.2 <| Finset.mem_inter.mp hx₂ |>.1;
                 · rw [ ← Finset.sum_union ];
                   · congr with j ; by_cases hj : j ∈ S <;> aesop;
                   · exact Finset.disjoint_left.mpr fun x hx₁ hx₂ => Finset.mem_sdiff.mp hx₁ |>.2 <| Finset.mem_inter.mp hx₂ |>.1;
               grind;
             · rw [ ← Finset.sum_union_inter ] ; ring;
           · simp +decide only [← sum_add_distrib, ← sum_sub_distrib];
             exact Finset.sum_congr rfl fun i hi => by rw [ ← Finset.sum_union_inter ] ; ring;
           · simp +decide only [← sum_add_distrib, ← sum_sub_distrib];
             exact Finset.sum_congr rfl fun i hi => by rw [ ← Finset.sum_union_inter ] ; ring;

end CausalNet

end
